using DevOpsHub.Application.Workflows;
namespace DevOpsHub.Infrastructure.Workflows;
public sealed class WorkflowService:IWorkflowService { private readonly List<ApprovalRequestDto> _items=[new(Guid.NewGuid(),"Production deployment v2.14.0","Release approval","Platform Team","Pending",DateTime.UtcNow)]; public IReadOnlyList<ApprovalRequestDto> GetAll()=>_items.OrderByDescending(x=>x.CreatedAt).ToList(); public ApprovalRequestDto Create(CreateApprovalRequest r){var x=new ApprovalRequestDto(Guid.NewGuid(),r.Title,r.Type,r.Requester,"Pending",DateTime.UtcNow);_items.Add(x);return x;} public ApprovalRequestDto Decide(Guid id,string decision){var i=_items.FindIndex(x=>x.Id==id);if(i<0)throw new KeyNotFoundException(); var x=_items[i] with{Status=decision};_items[i]=x;return x;} }
